const $=id=>document.getElementById(id);
const reduced=matchMedia('(prefers-reduced-motion: reduce)').matches;
let phase='intro',round=0,choices=[],busy=false;
const outcomes=(you,mira)=>[ (you==='keep'?3:0)+(mira==='share'?6:0), (mira==='keep'?3:0)+(you==='share'?6:0) ];
const foxMood=mood=>{$('fox').setAttribute('class','fox '+mood);$('fox').setAttribute('aria-label','Your '+mood+' fox guide');};
function coins(a,b){[ ['your',a],['mira',b] ].forEach(([who,n])=>{$(who+'Coins').textContent=n;const pile=$(who+'Pile');while(pile.children.length>n)pile.lastChild.remove();while(pile.children.length<n){const coin=document.createElement('i');coin.className='coin';pile.append(coin);}});}
function text(title,speech,button,instruction='',mood='thinking'){ $('title').textContent=title;$('speech').textContent=speech;$('next').textContent=button;$('instruction').textContent=instruction;foxMood(mood); }
function render(){
 const isCase=phase.startsWith('case');$('scene').classList.toggle('case',isCase);$('scene').classList.toggle('night',phase==='result'||phase==='compare'||phase==='explain'||phase==='case2'||phase==='case3');$('recap').hidden=!['compare','explain'].includes(phase);$('source').hidden=!isCase;$('choiceButtons').hidden=phase!=='choice';$('next').hidden=phase==='choice';$('next').disabled=busy;$('note').textContent='';$('sceneCaption').textContent=isCase?'Historical example · United States':'Coins in this round';$('kicker').textContent=isCase?'Real-world example 1':phase==='explain'?'The idea you just discovered':'The coin camp';
 const progress=({intro:0,rules:1,choice:2+round,result:2+round,compare:6,explain:7,case1:8,case2:9,case3:10,end:11})[phase];$('progress').innerHTML=Array.from({length:12},(_,i)=>`<i class="${i<=progress?'filled':''}"></i>`).join('');$('progress').setAttribute('aria-label',`Story step ${progress+1} of 12`);
 $('time').textContent=isCase?(phase==='case1'?'Before the ban':'January 1971'):(phase==='result'||phase==='compare'||phase==='explain'?'Coin camp · Night':'Coin camp · Morning');
 if(phase==='intro'){coins(3,3);$('yourAction').textContent='Your bag';$('miraAction').textContent='Her bag';text('Three coins. Two friends.','You and Mira each have 3 coins. Let’s see what happens when you share them.','Meet the magic rule','','happy');}
 if(phase==='rules'){text('A gift doubles!','Share your 3 coins, and Mira gets 6. If she shares hers, you get 6. Keep your bag, and its 3 coins stay yours.','Let’s try it','Each new try starts with 3 coins each.','happy');}
 if(phase==='choice'){
  coins(3,3);const mira=round<2?'share':'keep';$('yourAction').textContent='Your move';$('miraAction').textContent=mira==='share'?'Will share 3 → you get 6':'Will keep her 3';
  const forced=round%2===1?(choices[round-1]==='share'?'keep':'share'):null;
  text(round<2?'Mira shares her bag.':'Mira keeps her bag.',forced?`Let’s rewind. Mira makes the same move. What happens if you ${forced} your coins instead?`:`Mira will ${mira} her coins. What will you do with yours?`,'','Tap your move below. Then watch night fall.','thinking');
  document.querySelectorAll('[data-choice]').forEach(b=>{b.hidden=!!forced&&b.dataset.choice!==forced;b.disabled=busy;});
 }
 if(phase==='result'){
  const you=choices[round],mira=round<2?'share':'keep',[a,b]=outcomes(you,mira);$('yourAction').textContent=you==='share'?'You shared':'You kept';$('miraAction').textContent=mira==='share'?'Mira shared':'Mira kept';coins(a,b);
  const lines={ 'share,share':'You gave each other 6 coins. Sharing helped you both!', 'keep,share':'You kept 3 and got 6 from Mira. You have 9—but she has none.', 'share,keep':'You gave Mira 6. She kept her 3. You have none; she has 9.', 'keep,keep':'You both kept your bags. Just 3 coins each. Nobody gave a gift.' };
  text(`You: ${a} coins. Mira: ${b}.`,lines[you+','+mira],round===3?'See the pattern':round===1?'Now Mira keeps her bag':'Try my other move','This is one possible outcome, not a right or wrong answer.',a===6&&b===6?'happy':a===b?'worried':'surprised');
 }
 if(['compare','explain'].includes(phase)){coins(3,3);$('yourAction').textContent='Both keep';$('miraAction').textContent='Both keep';}
 if(phase==='compare')text('A tempting move. A smaller reward.','Keeping gives you more either way: 9 instead of 6, or 3 instead of 0. Mira faces the same temptation. But if you both keep, you both get less than if you shared.','What is this called?','Look: sharing together gives each of you twice as much.','worried');
 if(phase==='explain')text('The prisoner’s dilemma','A choice that helps you on your own can leave both of you worse off when you both make it. Here, keeping is tempting. Sharing together pays you both more.','Show me a real-world example','You just played the idea. No prisoners needed.','happy');
 if(isCase){$('tv').textContent=phase==='case1'?'TV ads':'Ads off';$('tv').classList.toggle('off',phase!=='case1');$('caseIcon').textContent=phase==='case3'?'🪙':'📻';}
 if(phase==='case1')text('The advertising race','Imagine two rival brands. Each wants attention, so each feels pressure to advertise—even when both might prefer to spend less.','What changed?','A simplified comparison to our coin game.','thinking');
 if(phase==='case2')text('Then the rules changed.','In January 1971, US cigarette ads were banned on TV and radio. Both rivals lost the same advertising move.','Who could benefit?','','surprised');
 if(phase==='case3'){text('A surprising twist','The study found signs that investors expected established tobacco firms to benefit. The authors pointed to fewer opportunities for new brands and the end of required anti-smoking broadcasts.','Finish this story','Connection: changing the rules can change everyone’s incentives.','thinking');$('note').textContent='The paper is more complicated than our coin game. It does not prove the ban’s health effects.';}
 if(phase==='end'){text('You found the dilemma.','Both want to do better for themselves. Both can end up with less. That’s the trap we explored.','Play the coin story again','','happy');$('note').textContent='You’ve finished this story.';}
}
const buttons=document.createElement('div');buttons.id='choiceButtons';buttons.style.cssText='display:flex;gap:10px;margin-top:12px';buttons.innerHTML='<button class="next" data-choice="share">Share my 3 coins</button><button class="next" data-choice="keep">Keep my 3 coins</button>';$('next').before(buttons);
const pause=ms=>new Promise(r=>setTimeout(r,ms));
async function choose(choice){if(busy||phase!=='choice')return;busy=true;choices[round]=choice;document.querySelectorAll('[data-choice]').forEach(b=>b.disabled=true);$('restart').disabled=true;$('scene').classList.add('night');$('time').textContent='Coin camp · Night';$('speech').textContent='Let’s count what each of you gets…';foxMood('surprised');const mira=round<2?'share':'keep';$('yourAction').textContent=choice==='share'?'You share':'You keep';$('miraAction').textContent=mira==='share'?'Mira shares':'Mira keeps';coins(choice==='keep'?3:0,mira==='keep'?3:0);if(choice==='share'||mira==='share'){$('scene').classList.add('sending');document.querySelector('.transfer').classList.toggle('reverse',choice==='keep');}await pause(reduced?0:1000);const [a,b]=outcomes(choice,mira);$('scene').classList.add('counting');for(let i=1;i<=Math.max(a,b);i++){coins(Math.min(i,a),Math.min(i,b));await pause(reduced?0:85);}$('scene').classList.remove('sending','counting');busy=false;$('restart').disabled=false;phase='result';render();$('announce').textContent=`Night has fallen. You have ${a} coins. Mira has ${b} coins.`;}
document.querySelectorAll('[data-choice]').forEach(b=>b.onclick=()=>choose(b.dataset.choice));
$('next').onclick=()=>{if(busy)return;if(phase==='intro')phase='rules';else if(phase==='rules')phase='choice';else if(phase==='result'){if(round<3){round++;phase='choice';}else phase='compare';}else phase=({compare:'explain',explain:'case1',case1:'case2',case2:'case3',case3:'end',end:'intro'})[phase];if(phase==='intro'){round=0;choices=[];}render();};
$('restart').onclick=()=>{if(busy)return;phase='intro';round=0;choices=[];render();};render();
